await sdk.dm('Bravo', 'Alpha here: Im doing Lumbridge courtyard+east fields+swamp+castle. You take Draynor, manor, Al Kharid, wizards tower. Log your kills in bots/_team/notes.md so we dont overlap. GL');
console.log('dm sent');

const killed = new Set(['Man']);
const skip = new Set(['Butterfly','Hans','Cook','Priest','Fishing spot','Swamp bubbles']);
let score = Math.log(2); // Man lvl2
const t0 = Date.now();
const DEADLINE = 1792762400187;
const loopEnd = t0 + 220000; // this call's budget

async function eatIfNeeded() {
  if (sdk.getState().player.hp <= 5) {
    const r = await bot.eatFood(/bread|shrimps/i);
    console.log('ate:', JSON.stringify(r && r.message));
  }
}

while (Date.now() < loopEnd && Date.now() < DEADLINE) {
  const s = sdk.getState();
  if (s.player.hp <= 4) await eatIfNeeded();
  const npcs = (s.nearbyNpcs || []).filter(n => n.reachable && n.combatLevel >= 1 && !skip.has(n.name) && !killed.has(n.name));
  if (!npcs.length) {
    // move east toward fields
    console.log('no new targets, walking east');
    await bot.walkTo(3245, 3255, 3);
    await sdk.waitForTicks(3);
    continue;
  }
  // prefer new species, higher level first
  npcs.sort((a, b) => b.combatLevel - a.combatLevel);
  const target = npcs[0];
  const name = target.name;
  console.log(`attacking ${name} (${target.combatLevel}) at ${Date.now() - t0}ms`);
  const atk = await bot.attack(target);
  console.log('  ->', atk && atk.message);
  if (!atk || !atk.success) {
    skip.add(name + ':' + target.index); // avoid re-picking same instance
    await sdk.waitForTicks(2);
    continue;
  }
  // wait for death of this instance
  let died = false;
  const end = Date.now() + 30000;
  while (Date.now() < end) {
    await sdk.waitForTicks(3);
    const cur = sdk.getState();
    if (cur.player.hp <= 5) await eatIfNeeded();
    const still = (cur.nearbyNpcs || []).find(n => n.index === target.index);
    if (!still) { died = true; break; }
    if (!cur.player.combat || true) {}
  }
  if (died) {
    killed.add(name);
    score += Math.log(1 + target.combatLevel);
    console.log(`KILLED ${name} (${target.combatLevel}) score=${score.toFixed(2)} species=${killed.size}`);
  } else {
    console.log(`timeout on ${name}, moving on`);
  }
}
console.log('SPECIES:', [...killed].join(', '));
return { score: score.toFixed(2), species: killed.size, list: [...killed], hp: sdk.getState().player.hp, pos: [sdk.getState().player.worldX, sdk.getState().player.worldZ] };

